from pathlib import Path
import re
p = Path('tests/validate_sigma.py')
s = p.read_text()

start = s.index("def _tokenize(cond: str):")
end = s.index("# --------------------------------------------------------------------------- #\n# 3. corpus-driven detection test")
new_block = '''TOKEN_RE = re.compile(
    r"\\(|\\)|\\b(?:and|or|not)\\b|\\b(?:1|any|all|none)\\s+of\\s+[\\w*]+|[A-Za-z_][\\w*]*")


def tokenize(cond: str) -> list[str]:
    toks = TOKEN_RE.findall(cond)
    rebuilt = "".join(toks).split()
    leftover = re.sub(r"\\s+", " ", cond).strip()
    if " ".join(rebuilt).replace("  ", " ") != " ".join(leftover.split()) and \\
            "".join(toks).replace(" ", "") != leftover.replace(" ", ""):
        raise DetectionError(f"condition contains unsupported tokens: {cond!r}")
    return toks


class _Parser:
    """Recursive-descent parser for the Sigma condition grammar:
       or_expr := and_expr ('or' and_expr)*
       and_expr := not_expr ('and' not_expr)*
       not_expr := 'not' not_expr | primary
       primary  := '(' or_expr ')' | '<quant> of <glob>' | identifier"""

    def __init__(self, toks, searches):
        self.toks, self.i, self.searches = toks, 0, searches

    def peek(self):
        return self.toks[self.i] if self.i < len(self.toks) else None

    def next(self):
        tok = self.peek()
        self.i += 1
        return tok

    def parse(self):
        node = self.or_expr()
        if self.i != len(self.toks):
            raise DetectionError(f"unparsed tokens in condition: {self.toks[self.i:]}")
        return node

    def or_expr(self):
        parts = [self.and_expr()]
        while self.peek() == "or":
            self.next()
            parts.append(self.and_expr())
        return ("or", parts) if len(parts) > 1 else parts[0]

    def and_expr(self):
        parts = [self.not_expr()]
        while self.peek() == "and":
            self.next()
            parts.append(self.and_expr())
        return ("and", parts) if len(parts) > 1 else parts[0]

    def not_expr(self):
        if self.peek() == "not":
            self.next()
            return ("not", self.not_expr())
        return self.primary()

    def _resolve(self, name: str):
        names = set(self.searches)
        if "*" in name:
            matched = [n for n in names if re.fullmatch(name.replace("*", ".*"), n)]
            if not matched:
                raise DetectionError(f"condition wildcard '{name}' matches no search identifier")
            return sorted(matched)
        if name not in names:
            raise DetectionError(f"condition references undefined search identifier '{name}'")
        return [name]

    def primary(self):
        tok = self.next()
        if tok is None:
            raise DetectionError("unexpected end of condition")
        if tok == "(":
            node = self.or_expr()
            if self.next() != ")":
                raise DetectionError("unbalanced parentheses in condition")
            return node
        m = re.fullmatch(r"(1|any|all|none)\\s+of\\s+([\\w*]+)", tok.replace("\\\\s+", " "))
        if m:
            quant, pattern = m.group(1), m.group(2)
            matched = self._resolve(pattern)
            leaves = [("leaf", n) for n in matched]
            if quant in ("1", "any"):
                return ("or", leaves)
            if quant == "all":
                return ("and", leaves)
            return ("not", ("or", leaves))
        leaves = [("leaf", n) for n in self._resolve(tok)]
        return leaves[0] if len(leaves) == 1 else ("or", leaves)


def _eval_node(node, searches: dict, event: dict) -> bool:
    kind = node[0]
    if kind == "leaf":
        return match_search(searches[node[1]], event)
    if kind == "and":
        return all(_eval_node(c, searches, event) for c in node[1])
    if kind == "or":
        return any(_eval_node(c, searches, event) for c in node[1])
    if kind == "not":
        return not _eval_node(node[1], searches, event)
    raise DetectionError(f"bad parse node: {node!r}")


def compile_condition(cond: str, searches: dict):
    """Compile a Sigma condition into a predicate over a process event dict."""
    toks = tokenize(cond)
    if not toks:
        raise DetectionError("empty condition")
    tree = _Parser(toks, searches).parse()

    def evaluate(event: dict) -> bool:
        return _eval_node(tree, searches, event)

    evaluate({})  # smoke test: no undefined identifiers at runtime
    return evaluate


