#!/usr/bin/env python3
"""
Validate a Sigma rule (Linux process_creation) without pySigma:

  1. YAML must parse (yaml.safe_load) - round-trip / duplicate-key checks.
  2. Sigma spec structural checks: required fields, UUID, dates, level, status,
     tags, logsource, detection/condition presence, allowed modifiers.
  3. Condition sanity: every referenced identifier exists, no dangling searches.
  4. Logic simulation: compile the search selections into a tiny evaluator and
     run them against a corpus of benign + malicious process-creation events so
     true/false positives are actually measured, not assumed.

Usage: python3 validate_sigma.py <rule.yml> [--corpus corpus.json]
"""
from __future__ import annotations

import argparse
import datetime as dt
import json
import re
import sys
from pathlib import Path

import yaml

ALLOWED_MODIFIERS = {
    None, "contains", "startswith", "endswith", "fieldref", "iif",
    "all", "base64", "base64offset", "wide", "startswith|all",
    "endswith|all", "contains|all", "re", "cidr", "lt", "lte", "gt", "gte",
    "exists", "exists|all",
}
REQUIRED_TOP = ["title", "id", "status", "description", "logsource", "detection", "level"]
VALID_STATUS = {"stable", "test", "experimental", "deprecated", "unsupported"}
VALID_LEVEL = {"informational", "low", "medium", "high", "critical"}
VALID_TAGS_PREFIX = ("attack.", "direction.", "network.", "file.", "process.", "registry.", "database.", "promote.")
UUID_RE = re.compile(r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-"[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$") if False else re.compile(
    r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$")


# --------------------------------------------------------------------------- #
# 1. YAML / structural validation
# --------------------------------------------------------------------------- #
class DuplicateKeyLoader(yaml.SafeLoader):
    """SafeLoader that errors on duplicate mapping keys (silently dropped keys
    would silently weaken a detection rule)."""


def _no_dupes(loader, node, deep=False):
    mapping = {}
    for key_node, value_node in node.value:
        key = loader.construct_object(key_node, deep=deep)
        if key in mapping:
            raise yaml.YAMLError(
                f"duplicate mapping key '{key}' at line {key_node.start_mark.line + 1}")
        mapping[key] = loader.construct_object(value_node, deep=deep)
    return mapping


DuplicateKeyLoader.add_constructor(yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG, _no_dupes)


def load_rule(path: Path):
    raw = path.read_text(encoding="utf-8")
    doc = yaml.load(raw, Loader=DuplicateKeyLoader)          # strict: dup keys
    yaml.safe_load(raw)                                      # canonical parser
    json.dumps(doc, default=str)                             # must be plain data
    dt.datetime.strptime  # (kept for clarity: dates validated below)
    return raw, doc


def structural_checks(doc) -> list[str]:
    errs, warns = [], []
    if not isinstance(doc, dict):
        return ["top level of the rule must be a mapping"]

    for field in REQUIRED_TOP:
        if field not in doc:
            errs.append(f"missing required field: {field}")

    rid = doc.get("id", "")
    if not (isinstance(rid, str) and UUID_RE.match(rid)):
        errs.append(f"'id' must be a UUID v4 string, got: {rid!r}")
    else:
        try:
            u = int(rid.replace("-", ""), 16)
            if not (u >> 76) & 0xF == 4:
                warns.append("'id' is not a UUID version 4")
        except ValueError:
            pass

    if doc.get("status") not in VALID_STATUS:
        errs.append(f"'status' must be one of {sorted(VALID_STATUS)}")
    if doc.get("level") not in VALID_LEVEL:
        errs.append(f"'level' must be one of {sorted(VALID_LEVEL)}")

    for dfield in ("date", "modified"):
        val = doc.get(dfield)
        if val is None:
            if dfield == "date":
                warns.append("recommended field 'date' is missing")
            continue
        if not isinstance(val, str):
            warns.append(f"'{dfield}' should be a quoted YYYY-MM-DD string (got {type(val).__name__}: {val!r})")
            continue
        try:
            dt.datetime.strptime(val, "%Y-%m-%d")
        except ValueError:
            errs.append(f"'{dfield}' is not ISO-8601 YYYY-MM-DD: {val!r}")

    refs = doc.get("references")
    if not isinstance(refs, list) or not refs:
        warns.append("'references' should list at least one URL")
    else:
        for r in refs:
            if not isinstance(r, str) or not r.startswith(("http://", "https://")):
                errs.append(f"reference must be a URL: {r!r}")

    tags = doc.get("tags")
    if not isinstance(tags, list) or not tags:
        warns.append("'tags' should include MITRE ATT&CK tags")
    else:
        for t in tags:
            if not isinstance(t, str) or not t.startswith(VALID_TAGS_PREFIX):
                errs.append(f"malformed tag: {t!r}")
            elif t.startswith("attack.") and not re.match(
                    r"^attack\.([a-z0-9_]+|t\d{4}(\.\d{3})?)$", t):
                errs.append(f"tag does not look like a valid ATT&CK id/name: {t!r}")

    ls = doc.get("logsource")
    if not isinstance(ls, dict) or not ls:
        errs.append("'logsource' must be a non-empty mapping")
    else:
        if not any(k in ls for k in ("product", "category", "service", "definition")):
            warns.append("logsource has no product/category/service selector")
        for bad in ("detection", "keywords"):
            if bad in ls:
                errs.append(f"logsource must not contain '{bad}'")

    rel = doc.get("related")
    if rel is not None:
        if not isinstance(rel, list):
            errs.append("'related' must be a list")
        else:
            for r in rel:
                if not isinstance(r, dict) or "id" not in r or "type" not in r:
                    errs.append(f"related entries need id+type: {r!r}")
                elif r["type"] not in {"similar", "same", "derived", "obsolete", "merged"}:
                    errs.append(f"invalid related type: {r['type']!r}")

    fp = doc.get("falsepositives")
    if fp is not None and (not isinstance(fp, list) or any(not isinstance(x, str) for x in fp)):
        errs.append("'falsepositives' must be a list of strings")
    if not isinstance(doc.get("description"), str) or len(str(doc.get("description"))) < 40:
        warns.append("'description' should be a meaningful string")
    return errs, warns


# --------------------------------------------------------------------------- #
# 2. detection / condition validation + tiny evaluator
# --------------------------------------------------------------------------- #
class DetectionError(Exception):
    pass


def parse_searches(det: dict):
    searches = {k: v for k, v in det.items() if k != "condition"}
    if not searches:
        raise DetectionError("detection contains no search definitions")
    for name, sel in searches.items():
        _check_selector(name, sel)
    return searches


def _check_selector(name: str, sel):
    blocks = sel if isinstance(sel, list) else [sel]
    if not isinstance(sel, (dict, list)) or not blocks:
        raise DetectionError(f"search '{name}' must be a mapping or non-empty list of mappings")
    for blk in blocks:
        if not isinstance(blk, dict) or not blk:
            raise DetectionError(f"search '{name}' contains a non-mapping/empty selector block")
        for key, vals in blk.items():
            if key.startswith(("keywords", "condition")):
                continue
            parts = key.split("|")
            field, modifiers = parts[0], parts[1:]
            if not field:
                raise DetectionError(f"search '{name}': empty field name in '{key}'")
            for m in modifiers:
                if m not in ALLOWED_MODIFIERS:
                    raise DetectionError(f"search '{name}': unsupported modifier '{m}' in '{key}'")
            if not isinstance(vals, list):
                vals = [vals]
            for v in vals:
                if not isinstance(v, (str, int, float, bool)):
                    raise DetectionError(f"search '{name}': non-scalar value {v!r} for '{key}'")


def _match_block(block: dict, event: dict) -> bool:
    """One selector block: AND across fields; 'contains|all' ANDs its values."""
    for key, vals in block.items():
        field, mods = key.split("|")[0], key.split("|")[1:]
        if field == "keywords":
            hay = " ".join(str(v) for v in event.values())
            vals = vals if isinstance(vals, list) else [vals]
            if "all" in mods:
                if not all(str(v).lower() in hay.lower() for v in vals):
                    return False
            elif not any(str(v).lower() in hay.lower() for v in vals):
                return False
            continue
        if field not in event:
            return False
        raw = event[field]
        hay = raw if isinstance(raw, str) else " ".join(str(x) for x in raw)
        hay = str(hay)
        vals = [str(v) for v in (vals if isinstance(vals, list) else [vals])]
        test = {
            None: lambda h, v: h.lower() == v.lower(),
            "contains": lambda h, v: v.lower() in h.lower(),
            "startswith": lambda h, v: h.lower().startswith(v.lower()),
            "endswith": lambda h, v: h.lower().endswith(v.lower()),
            "re": lambda h, v: re.search(v, h) is not None,
        }
        for m in mods:
            if m in ("all", "case_sensitive"):
                continue
            if m not in test:
                raise DetectionError(f"modifier '{m}' not implemented in simulator")
        fn = test["contains" if "contains" in mods else
                   "startswith" if "startswith" in mods else
                   "endswith" if "endswith" in mods else
                   "re" if "re" in mods else None]
        if "all" in mods:
            if not all(fn(hay, v) for v in vals):
                return False
        elif not any(fn(hay, v) for v in vals):
            return False
    return True


def match_search(sel, event: dict) -> bool:
    """Search definitions: list of blocks -> OR (with 'all' -> AND)."""
    if isinstance(sel, dict):
        return _match_block(sel, event)
    if isinstance(sel, list) and sel and all(isinstance(x, dict) for x in sel):
        return any(_match_block(b, event) for b in sel)
    raise DetectionError(f"cannot evaluate selector: {sel!r}")


def match_all_searches(sel, event: dict) -> bool:
    if isinstance(sel, dict):
        return _match_block(sel, event)
    return all(_match_block(b, event) for b in sel)


def _tokenize(cond: str):
    return re.findall(r"\(|\)|\bnot\b|\band\b|\bor\b|\b[\w*]+\b|[\d*]+", cond)


def compile_condition(cond: str, searches: dict):
    """Compile a Sigma condition (subset: and/or/not, groups, N of pattern,
    keyword 'all' and identifier wildcards) into a python lambda(event)."""
    names = set(searches)
    cond = " ".join(cond.split())
    # validate identifiers
    for tok in re.findall(r"[A-Za-z_][\w*]*", cond):
        if tok in {"and", "or", "not", "of", "1", "all", "any", "key"}:
            continue
        if "*" in tok:
            if not any(re.fullmatch(tok.replace("*", ".*"), n) for n in names):
                raise DetectionError(f"condition wildcard '{tok}' matches no search identifier")
        elif tok not in names:
            raise DetectionError(f"condition references undefined search identifier '{tok}'")

    # rewrite "1 of filter_*" / "all of sel_*" / "none of x"
    def expand(match):
        quantifier, pattern = match.group(1), match.group(2)
        matched = [n for n in names if re.fullmatch(pattern.replace("*", ".*"), n)]
        if not matched:
            raise DetectionError(f"'{match.group(0)}' matches no search identifier")
        op = {"1": "any", "any": "any", "all": "all", "none": "none"}[quantifier.lower()]
        inner = " or ".join(f"__S('{n}')" for n in matched) if op != "all" else \
               " and ".join(f"__S('{n}')" for n in matched)
        if op == "none":
            inner = " or ".join(f"__S('{n}')" for n in matched)
            return f"(not ({inner}))"
        return f"({inner})"

    expr = re.sub(r"\b(1|any|all|none)\s+of\s+([\w*]+)", expand, cond)
    expr = re.sub(r"\b(and|or|not)\b", lambda m: m.group(1).upper(), expr)
    expr = re.sub(r"\b([A-Za-z_][\w]*)\b(?!\()", lambda m: f"__S('{m.group(1)}')", expr)
    expr = expr.replace("AND", "and").replace("OR", "or").replace("NOT", "not")

    def make(event):
        def __S(name):
            if name not in searches:
                raise DetectionError(f"condition referenced undefined identifier '{name}'")
            return match_search(searches[name], event)
        return eval(expr, {"__S": __S, "__builtins__": {}}, {})  # noqa: S307 - local validator

    # sanity: must be callable & boolean
    make({})
    return make


# --------------------------------------------------------------------------- #
# 3. corpus-driven detection test
# --------------------------------------------------------------------------- #
def run_corpus(evaluate, corpus_path: Path):
    cases = json.loads(corpus_path.read_text(encoding="utf-8"))
    fails, rows = [], []
    for case in cases:
        got = bool(evaluate(case["event"]))
        want = bool(case["expect"])
        rows.append((case["name"], got, want, case.get("note", "")))
        if got != want:
            fails.append((case["name"], got, want, case.get("note", "")))
    return rows, fails


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("rule")
    ap.add_argument("--corpus")
    args = ap.parse_args()

    path = Path(args.rule)
    print(f"== validating {path}")
    try:
        raw, doc = load_rule(path)
    except yaml.YAMLError as exc:
        print(f"FAIL: YAML did not parse: {exc}")
        return 2
    print(f"OK : YAML parses ({len(raw.splitlines())} lines, "
          f"{len(yaml.safe_load(raw).get('detection', {}))} detection keys)")

    errs, warns = structural_checks(doc)
    for e in errs:
        print("FAIL:", e)
    for w in warns:
        print("WARN:", w)

    det = doc.get("detection", {})
    try:
        searches = parse_searches(det)
        print(f"OK : {len(searches)} search identifiers, modifiers valid")
        cond = det.get("condition")
        if not isinstance(cond, str) or not cond.strip():
            raise DetectionError("detection.condition missing")
        evaluate = compile_condition(cond, searches)
        print(f"OK : condition resolves -> {' '.join(cond.split())}")
    except DetectionError as exc:
        print("FAIL:", exc)
        return 2

    print("INFO : search identifiers: " + ", ".join(sorted(searches)))

    rc = 0 if not errs else 1
    if args.corpus:
        rows, fails = run_corpus(evaluate, Path(args.corpus))
        tp = sum(1 for n, g, w, _ in rows if w and g)
        tn = sum(1 for n, g, w, _ in rows if not w and not g)
        print(f"\n== corpus: {len(rows)} events | true positives {tp} | true negatives {tn}")
        for name, got, want, note in rows:
            flag = "ok " if got == want else "FAIL"
            print(f"  [{flag}] {'ALERT   ' if got else 'no alert'}  {name}")
        for name, got, want, note in fails:
            rc = 1
            print(f"  FAIL: '{name}' -> alert={got}, expected {want}. {note}")
        if not fails:
            print("OK : every corpus event classified as expected")
    print("\n== RESULT:", "PASS" if rc == 0 else "FAIL")
    return rc


if __name__ == "__main__":
    sys.exit(main())

